-- Accessible contextual Bible Bee bank. Competitors need not be Bible experts.
on conflict(id) do nothing;
-- Align equivalent starter questions so daily concept deduplication avoids same-day paraphrases.
update private.buklod_bible_v4_questions set concept_key=case id
 when 'moses' then 'e.moses' when 'goliath' then 'e.david' when 'bethlehem' then 'e.bethlehem'
 when 'ark' then 'e.noah' when 'r3_e1' then 'e.mary' when 'r3_e10' then 'e.abraham'
 when 'r3_m3' then 'm.hannah' when 'r3_h7' then 'm.eunice' else concept_key end
where id in ('moses','goliath','bethlehem','ark','r3_e1','r3_e10','r3_m3','r3_h7');
